class Solution {
    private int maxSum;

    public int maxPathSum(TreeNode root) {
        maxSum = Integer.MIN_VALUE;
        dfs(root);
        return maxSum;
    }

    private int dfs(TreeNode node) {
        if (node == null) {
            return 0;
        }

        int leftGain = Math.max(0, dfs(node.left));
        int rightGain = Math.max(0, dfs(node.right));
        maxSum = Math.max(maxSum, node.val + leftGain + rightGain);
        return node.val + Math.max(leftGain, rightGain);
    }
}

class Solution {
    public int maxPathSum(TreeNode root) {
        return dfs(root).bestPath;
    }

    private Result dfs(TreeNode node) {
        if (node == null) {
            return new Result(Integer.MIN_VALUE, 0);
        }

        Result left = dfs(node.left);
        Result right = dfs(node.right);
        int leftGain = Math.max(0, left.extendableGain);
        int rightGain = Math.max(0, right.extendableGain);
        int pathThroughNode = node.val + leftGain + rightGain;
        int bestPath = Math.max(pathThroughNode, Math.max(left.bestPath, right.bestPath));
        int extendableGain = node.val + Math.max(leftGain, rightGain);
        return new Result(bestPath, extendableGain);
    }

    private static class Result {
        int bestPath;
        int extendableGain;

        Result(int bestPath, int extendableGain) {
            this.bestPath = bestPath;
            this.extendableGain = extendableGain;
        }
    }
}

import java.util.*;

class Solution {
    public int maxPathSum(TreeNode root) {
        int best = Integer.MIN_VALUE;
        Map<TreeNode, Integer> gain = new HashMap<>();
        Deque<TreeNode> stack = new ArrayDeque<>();
        TreeNode current = root;
        TreeNode lastVisited = null;

        while (current != null || !stack.isEmpty()) {
            while (current != null) {
                stack.push(current);
                current = current.left;
            }

            TreeNode node = stack.peek();
            if (node.right != null && lastVisited != node.right) {
                current = node.right;
            } else {
                int leftGain = Math.max(0, gain.getOrDefault(node.left, 0));
                int rightGain = Math.max(0, gain.getOrDefault(node.right, 0));
                best = Math.max(best, node.val + leftGain + rightGain);
                gain.put(node, node.val + Math.max(leftGain, rightGain));
                lastVisited = stack.pop();
            }
        }

        return best;
    }
}

import java.util.*;

class Solution {
    public int maxPathSum(TreeNode root) {
        List<TreeNode> order = new ArrayList<>();
        Deque<TreeNode> stack = new ArrayDeque<>();
        stack.push(root);

        while (!stack.isEmpty()) {
            TreeNode node = stack.pop();
            order.add(node);
            if (node.left != null) {
                stack.push(node.left);
            }
            if (node.right != null) {
                stack.push(node.right);
            }
        }

        int best = Integer.MIN_VALUE;
        for (int i = order.size() - 1; i >= 0; i--) {
            TreeNode node = order.get(i);
            int original = node.val;
            int leftGain = node.left == null ? 0 : Math.max(0, node.left.val);
            int rightGain = node.right == null ? 0 : Math.max(0, node.right.val);
            best = Math.max(best, original + leftGain + rightGain);
            node.val = original + Math.max(leftGain, rightGain);
        }

        return best;
    }
}
